import fs from 'node:fs';import assert from 'node:assert/strict';import {test} from 'node:test';import {lite,load,makeROM,write} from './helpers.mjs';
test('single-controller API reads every button through the actual bus',()=>{const c=lite();load(c,makeROM(0,1,0));c.NES.controller=new c.Controller();assert.equal(c.NES.keydown.length,1);assert.equal(c.NES.keyup.length,1);for(let button=0;button<8;button++){c.NES.keydown(button);write(c,0x4016,1);write(c,0x4016,0);for(let bit=0;bit<8;bit++)assert.equal(c.memory_read(0x4016),bit===button?0x41:0x40);c.NES.keyup(button);assert.equal(c.NES.controller.state[button],0x40);}assert.equal(c.NES.controllers,undefined);});
test('second port remains idle, independent of first-port keys and repeated strobes',()=>{const c=lite();load(c,makeROM(0,1,0));c.NES.controller=new c.Controller();for(let bit=0;bit<8;bit++)c.NES.keydown(bit);for(let run=0;run<3;run++){write(c,0x4016,1);write(c,0x4016,0);for(let index=0;index<48;index++){const bit=index%24;assert.equal(c.memory_read(0x4017),bit<8?64:bit===19?1:0);}}});
test('Mapper 30 rejected and no longer reserves banked CHR RAM',()=>{const c=lite();c.NES.parse(makeROM(30,2,0));assert.equal(c.NES.chr.length,1);assert.throws(()=>c.NES.load(),/Map30/);});
test('runtime source contains no multi-controller object/API or Mapper 30 branches',()=>{const text=['controller','nes','memory','ui','rom','mappers'].map(n=>fs.readFileSync(new URL('../source/'+n+'.js',import.meta.url),'utf8')).join('\n');assert.doesNotMatch(text,/NES\.controllers|controllers\[|mapper\s*===?\s*30|0,1,2,3,4,30/);const nes=fs.readFileSync(new URL('../source/nes.js',import.meta.url),'utf8');assert.equal((nes.match(/new Controller\(\)/g)||[]).length,1);});
